/* From Uiverse.io by htwarriors108 - Tags: card, hover, shadow, caller, hover effect, call reject, accept call, box-shadow, cardhover  */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  border-radius: 1em;
  flex-direction: column;
  justify-content: space-evenly;
  background-color: #080808;
  box-shadow: 0 0 2rem rgba(0, 0, 0, 0.8);
  cursor: pointer;
  transition: 0.2s ease-in-out;
  padding: 5px;
  color: #fff;
}

.__UIV_SCOPE__ .card:hover {
  rotate: 1deg;
  scale: 1.05;
}

.__UIV_SCOPE__ .card, .__UIV_SCOPE__ .imgBox, .__UIV_SCOPE__ .caller {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .imgBox {
  width: 6em;
  height: 6em;
  box-shadow: 0px 0.25em 1rem rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  justify-content: center;
}

.__UIV_SCOPE__ .imgBox svg {
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .name {
  width: 100%;
  text-align: center;
  font-weight: 900;
  transition: 1s ease-in-out;
}

.__UIV_SCOPE__ .name .p1 {
  font-size: 1.2em;
}

.__UIV_SCOPE__ .name .p2 {
  font-size: 0.8em;
  color: rgb(50, 146, 255);
}

.__UIV_SCOPE__ .caller {
  width: 100%;
  flex-direction: row;
  justify-content: space-evenly;
}

.__UIV_SCOPE__ .callerBtn {
  width: 2em;
  height: 2em;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  transition: 0.1s ease-in-out;
  animation: animate linear infinite 2s;
}

.__UIV_SCOPE__ .callerBtn:hover {
  scale: 1.1;
}

.__UIV_SCOPE__ #pick {
  background-color: #28ff28;
  box-shadow: 0px 3px 10px #28ff28;
}

.__UIV_SCOPE__ #end {
  background-color: #ff2828;
  box-shadow: 0px 3px 10px #ff2828;
}

.__UIV_SCOPE__ #end svg {
  rotate: 135deg;
}

@keyframes animate {
  0% {
    transform: translateY(0px);
  }

  50% {
    transform: translateY(3px) rotate(-10deg);
  }

  100% {
    transform: translateY(0px);
  }
}
